//! The interpolator (the `SMC_Interpolator` analogue): consumes a planned
//! geometry queue and produces per-cycle path setpoints.
//!
//! Motion along the path parameter `s` is generated by rsruckig as a 1-DoF
//! jerk-limited profile per segment: current `(s, ṡ, s̈)` → `(L, v_exit, 0)`,
//! where `v_exit` comes from the look-ahead plan, so segments blend without
//! stopping. Trajectories are computed offline per segment
//! ([`rsruckig`]'s `calculate`) and sampled with `Trajectory::at_time`
//! using our own time bookkeeping, so segment boundaries do not suffer
//! cycle-quantization errors. Feed-override changes, pause (override 0 /
//! halt) and resume simply retarget the profile from the current state.

use crate::error::CncError;
use crate::geometry::{GeoElem, GeoMove, Segment, SwitchPoint, SyncEvent};
use crate::lookahead::{LookAhead, PlannedSegment};
use crate::queue::GeoQueue;
use crate::types::{PathLimits, PathPoint};
use rsruckig::prelude::*;

/// Standstill threshold for the path velocity.
const EPS_V: f64 = 1e-9;
/// Override values below this snap to 0 (a slower crawl would produce
/// trajectory durations beyond rsruckig's supported range).
const MIN_OVERRIDE: f64 = 0.005;
/// Event slots pre-reserved in [`Interpolator::output_buffer`].
const EVENT_CAPACITY: usize = 4;

/// Non-panicking rsruckig error handler.
///
/// Every rsruckig problem is returned as `Err` and converted into
/// [`CncError::Otg`]; rscnc never installs a handler that panics or aborts,
/// because on `wasm32-unknown-unknown` a panic is an unrecoverable trap and
/// there is no unwinding to recover from it.
#[derive(Debug, Default, Clone, Copy)]
struct ReturnErrorHandler;

impl RuckigErrorHandler for ReturnErrorHandler {
    fn handle_validation_error(message: &str) -> Result<(), RuckigError> {
        Err(RuckigError::ValidationError(message.to_string()))
    }

    fn handle_calculator_error(message: &str) -> Result<(), RuckigError> {
        Err(RuckigError::CalculatorError(message.to_string()))
    }
}

/// Interpolator state (the `SMC_INT_STATUS` analogue).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum IplState {
    /// No program loaded.
    #[default]
    Idle,
    /// Interpolating a move segment.
    Running,
    /// Executing a G4 dwell.
    Dwelling,
    /// Decelerating to standstill (override → 0 or halt).
    Pausing,
    /// At standstill; waiting for override > 0 / resume.
    Paused,
    /// Single-step mode: stopped at a segment boundary, waiting for `step()`.
    StepHold,
    /// Program complete.
    Finished,
}

/// Per-cycle interpolator output.
///
/// For real-time use do not build one per cycle: create a single buffer with
/// [`Interpolator::output_buffer`] and fill it with
/// [`Interpolator::cycle_into`], which reuses the buffer's existing capacity
/// and performs no heap allocation in steady state.
#[derive(Debug, Clone, Default)]
pub struct IplOutput {
    /// Interpolator state after this cycle.
    pub state: IplState,
    /// Position on the programmed path.
    pub path_position: PathPoint,
    /// Unit tangent of the path at the current point (zero for pure aux moves).
    pub path_tangent: PathPoint,
    /// Path speed ṡ ≥ 0.
    pub path_velocity: f64,
    /// Tangential path acceleration s̈.
    pub path_acceleration: f64,
    /// Auxiliary axis positions.
    pub aux: Vec<f64>,
    /// Auxiliary axis velocities.
    pub aux_velocity: Vec<f64>,
    /// Synchronized events crossed during this cycle.
    pub events: Vec<SyncEvent>,
    /// Switch points (`H` functions) crossed during this cycle, in the order
    /// they were passed.
    pub switch_points: Vec<SwitchPoint>,
    /// Source line of the current (or last) move.
    pub src_line: usize,
    /// Object number of the current (or last) move.
    pub obj_no: u32,
    /// Completed path length, including progress into the current segment.
    pub s_total: f64,
    /// Fraction of the total program path length completed (0..1).
    pub progress: f64,
}

impl IplOutput {
    /// An empty output with room for `n_aux` auxiliary axes and a few
    /// synchronized events, so that filling it never has to allocate.
    ///
    /// [`Interpolator::output_buffer`] sizes this from the loaded program and
    /// is normally the better choice.
    pub fn with_aux_capacity(n_aux: usize) -> Self {
        Self::with_capacity(n_aux, EVENT_CAPACITY)
    }

    /// An empty output with room for `n_aux` auxiliary axes and `n_switch`
    /// switch points, so that filling it never has to allocate.
    pub fn with_capacity(n_aux: usize, n_switch: usize) -> Self {
        Self {
            aux: Vec::with_capacity(n_aux),
            aux_velocity: Vec::with_capacity(n_aux),
            events: Vec::with_capacity(EVENT_CAPACITY),
            switch_points: Vec::with_capacity(n_switch),
            ..Self::default()
        }
    }
}

/// The path interpolator. [`load`](Self::load) a planned queue, then call
/// [`cycle`](Self::cycle) every control period; runtime control via
/// [`set_override`](Self::set_override), [`halt`](Self::halt) /
/// [`resume`](Self::resume) and [`set_single_step`](Self::set_single_step).
pub struct Interpolator {
    limits: PathLimits,
    lookahead: LookAhead,
    aux_max_velocity: Vec<f64>,
    cycle_time: f64,

    queue: Vec<GeoElem>,
    plan: Vec<PlannedSegment>,
    cursor: usize,
    plan_pos: usize,
    total_length: f64,

    otg: Ruckig<1, ReturnErrorHandler>,
    input: InputParameter<1>,
    traj: Trajectory<1>,
    traj_time: f64,
    traj_override: f64,
    /// Effective exit velocity the current trajectory was planned for.
    planned_v_exit: f64,
    /// Coordinate rebase for a stop trajectory that crosses segment boundaries.
    stop_s_offset: f64,

    state: IplState,
    s_local: f64,
    v_s: f64,
    a_s: f64,
    s_done: f64,
    dwell_remaining: f64,
    override_pct: f64,
    halted: bool,
    single_step: bool,
    step_pending: bool,
    time: f64,

    point: PathPoint,
    tangent: PathPoint,
    aux_now: Vec<f64>,
    aux_vel_now: Vec<f64>,
    /// Worst-case auxiliary axis count of the loaded program; the aux buffers
    /// are reserved for it at load time so the cycle never grows them.
    aux_capacity: usize,
    pending_events: Vec<SyncEvent>,
    /// Switch points crossed since the last output, and how far into the
    /// current move's list the interpolator has already reported.
    pending_switches: Vec<SwitchPoint>,
    switch_pos: usize,
    switch_capacity: usize,
    last_src_line: usize,
    last_obj_no: u32,
}

impl Interpolator {
    /// New idle interpolator. `aux_max_velocity` holds the velocity limits
    /// of the auxiliary axes in decoder order; `cycle_time` is the control
    /// period in seconds.
    pub fn new(
        limits: PathLimits,
        lookahead: LookAhead,
        aux_max_velocity: Vec<f64>,
        cycle_time: f64,
    ) -> Self {
        Self {
            limits,
            lookahead,
            aux_max_velocity,
            cycle_time,
            queue: Vec::new(),
            plan: Vec::new(),
            cursor: 0,
            plan_pos: 0,
            total_length: 0.0,
            otg: Ruckig::new(None, cycle_time),
            input: InputParameter::new(None),
            traj: Trajectory::new(None),
            traj_time: 0.0,
            traj_override: 1.0,
            planned_v_exit: 0.0,
            stop_s_offset: 0.0,
            state: IplState::Idle,
            s_local: 0.0,
            v_s: 0.0,
            a_s: 0.0,
            s_done: 0.0,
            dwell_remaining: 0.0,
            override_pct: 1.0,
            halted: false,
            single_step: false,
            step_pending: false,
            time: 0.0,
            point: [0.0; 3],
            tangent: [0.0; 3],
            aux_now: Vec::new(),
            aux_vel_now: Vec::new(),
            aux_capacity: 0,
            pending_events: Vec::with_capacity(EVENT_CAPACITY),
            pending_switches: Vec::with_capacity(EVENT_CAPACITY),
            switch_pos: 0,
            switch_capacity: EVENT_CAPACITY,
            last_src_line: 0,
            last_obj_no: 0,
        }
    }

    /// Load a (preprocessed) queue and run the look-ahead plan over it.
    /// Resets all runtime state; interpolation starts from rest at the
    /// first move's start point.
    ///
    /// The cycle time and the path limits are validated here: a degenerate
    /// configuration (non-finite, zero or negative cycle time / velocity /
    /// acceleration / jerk) is refused with [`CncError::Interpolator`]
    /// instead of being handed to the trajectory generator.
    ///
    /// All per-cycle buffers are sized for the loaded program here, so a
    /// steady-state [`cycle_into`](Self::cycle_into) allocates nothing.
    pub fn load(&mut self, queue: GeoQueue) -> Result<(), CncError> {
        self.check_config()?;
        self.plan = self
            .lookahead
            .plan(&queue, &self.limits, &self.aux_max_velocity);
        self.queue = queue.into_iter().collect();
        self.total_length = self.plan.iter().map(|p| p.length).sum();
        self.cursor = 0;
        self.plan_pos = 0;
        self.s_local = 0.0;
        self.v_s = 0.0;
        self.a_s = 0.0;
        self.s_done = 0.0;
        self.time = 0.0;
        self.traj_time = 0.0;
        self.step_pending = false;
        self.pending_events.clear();
        self.pending_switches.clear();
        self.switch_pos = 0;
        // Worst case for one cycle: every switch point of the busiest move.
        self.switch_capacity = self
            .queue
            .iter()
            .filter_map(|e| match e {
                GeoElem::Move(m) => Some(m.switch_points.len()),
                _ => None,
            })
            .max()
            .unwrap_or(0)
            .max(EVENT_CAPACITY);
        self.pending_switches.reserve(self.switch_capacity);
        // Worst-case aux width of the program: the per-cycle buffers are
        // reserved for it once, here, and never grow again.
        self.aux_capacity = self
            .queue
            .iter()
            .filter_map(|e| match e {
                GeoElem::Move(m) => Some(m.aux_start.len().max(m.aux_end.len())),
                _ => None,
            })
            .max()
            .unwrap_or(0);
        let mut aux = core::mem::take(&mut self.aux_now);
        let mut aux_vel = core::mem::take(&mut self.aux_vel_now);
        aux.clear();
        aux_vel.clear();
        aux.reserve(self.aux_capacity);
        aux_vel.reserve(self.aux_capacity);
        // Initial pose from the first move
        let point = if let Some(mv) = self.first_move() {
            aux.extend_from_slice(&mv.aux_start);
            aux_vel.resize(mv.aux_start.len(), 0.0);
            mv.geo.start()
        } else {
            [0.0; 3]
        };
        self.aux_now = aux;
        self.aux_vel_now = aux_vel;
        self.point = point;
        self.tangent = [0.0; 3];
        self.state = IplState::Running; // enter_next refines this
        self.enter_next(self.effective_override())?;
        Ok(())
    }

    /// Feed override factor (1.0 = 100%). Values below 0.5% snap to 0,
    /// which decelerates to a pause; raising it again resumes. A NaN factor
    /// is treated as 0 (pause) rather than propagated into the trajectory.
    pub fn set_override(&mut self, factor: f64) {
        self.override_pct = if factor >= MIN_OVERRIDE { factor } else { 0.0 };
    }

    /// The current feed override factor.
    pub fn override_factor(&self) -> f64 {
        self.override_pct
    }

    /// Decelerate to standstill and hold (independent of the override value).
    pub fn halt(&mut self) {
        self.halted = true;
    }

    /// Release a halt.
    pub fn resume(&mut self) {
        self.halted = false;
    }

    /// In single-step mode every segment ends at standstill and the
    /// interpolator waits for [`step`](Self::step) before continuing.
    pub fn set_single_step(&mut self, on: bool) {
        self.single_step = on;
    }

    /// Execute the next segment while in [`IplState::StepHold`].
    pub fn step(&mut self) {
        self.step_pending = true;
    }

    /// The current interpolator state.
    pub fn state(&self) -> IplState {
        self.state
    }

    /// The control period in seconds.
    pub fn cycle_time(&self) -> f64 {
        self.cycle_time
    }

    /// Total parameter length of the loaded program (the sum of all planned
    /// segment lengths, i.e. the denominator of
    /// [`IplOutput::progress`](IplOutput#structfield.progress)). 0 before a
    /// program is loaded.
    pub fn total_length(&self) -> f64 {
        self.total_length
    }

    /// Start point of the loaded path: the start of the program's first move,
    /// available immediately after [`load`](Self::load) and before the first
    /// cycle. `[0, 0, 0]` when the program contains no move.
    pub fn start_position(&self) -> PathPoint {
        self.first_move().map_or([0.0; 3], |mv| mv.geo.start())
    }

    /// Auxiliary axis positions at the start of the loaded path, in decoder
    /// order. Empty when the program contains no move.
    pub fn start_aux(&self) -> &[f64] {
        self.first_move().map_or(&[][..], |mv| &mv.aux_start)
    }

    /// Whether the path element the current output belongs to is a rapid
    /// (`G0`) move. Valid immediately after [`cycle`](Self::cycle) /
    /// [`cycle_into`](Self::cycle_into) — it refers to the same move the
    /// output pose was produced from — and after [`load`](Self::load) it
    /// refers to the program's first move. `false` when no move is loaded.
    pub fn current_is_rapid(&self) -> bool {
        self.current_or_last_move().is_some_and(|mv| mv.is_rapid)
    }

    /// Reject a degenerate configuration before it reaches rsruckig.
    fn check_config(&self) -> Result<(), CncError> {
        let bad = |what: &str, v: f64| {
            Err(CncError::Interpolator(format!(
                "{what} must be a finite number greater than zero (got {v})"
            )))
        };
        if !self.cycle_time.is_finite() || self.cycle_time <= 0.0 {
            return bad("cycle time", self.cycle_time);
        }
        if !self.limits.max_velocity.is_finite() || self.limits.max_velocity <= 0.0 {
            return bad("max_velocity", self.limits.max_velocity);
        }
        if !self.limits.max_acceleration.is_finite() || self.limits.max_acceleration <= 0.0 {
            return bad("max_acceleration", self.limits.max_acceleration);
        }
        if !self.limits.max_jerk.is_finite() || self.limits.max_jerk <= 0.0 {
            return bad("max_jerk", self.limits.max_jerk);
        }
        let a_n = self.limits.max_normal_acceleration;
        if !a_n.is_finite() || a_n < 0.0 {
            return Err(CncError::Interpolator(format!(
                "max_normal_acceleration must be a finite number greater than or equal to zero (got {a_n})"
            )));
        }
        if let Some((i, v)) = self
            .aux_max_velocity
            .iter()
            .enumerate()
            .find(|(_, v)| !v.is_finite() || **v < 0.0)
        {
            return Err(CncError::Interpolator(format!(
                "auxiliary axis {i} velocity limit must be a finite number greater than or equal to zero (got {v})"
            )));
        }
        if !self.lookahead.accel_margin.is_finite()
            || self.lookahead.accel_margin <= 0.0
            || !self.lookahead.junction_deviation.is_finite()
            || self.lookahead.junction_deviation < 0.0
        {
            return Err(CncError::Interpolator(format!(
                "look-ahead parameters are degenerate (accel_margin {}, junction_deviation {})",
                self.lookahead.accel_margin, self.lookahead.junction_deviation
            )));
        }
        Ok(())
    }

    fn effective_override(&self) -> f64 {
        if self.halted {
            0.0
        } else {
            self.override_pct
        }
    }

    /// Advance one control cycle, returning a freshly allocated output.
    ///
    /// This is a convenience wrapper around [`cycle_into`](Self::cycle_into);
    /// it allocates the output's `aux`, `aux_velocity` and `events` vectors on
    /// every call. Real-time callers should keep one buffer from
    /// [`output_buffer`](Self::output_buffer) and use `cycle_into`.
    pub fn cycle(&mut self) -> Result<IplOutput, CncError> {
        let mut out = IplOutput::with_capacity(self.aux_capacity, self.switch_capacity);
        self.cycle_into(&mut out)?;
        Ok(out)
    }

    /// Advance one control cycle, writing the result into an existing output
    /// buffer.
    ///
    /// The buffer's vectors are cleared and refilled, reusing their capacity:
    /// with a buffer from [`output_buffer`](Self::output_buffer) a
    /// steady-state cycle — segment boundaries included — performs **zero**
    /// heap allocations. (A cycle that emits synchronized events still
    /// allocates for the event payloads themselves.)
    ///
    /// On error the buffer is left untouched.
    pub fn cycle_into(&mut self, out: &mut IplOutput) -> Result<(), CncError> {
        self.advance()?;
        self.fill_output(out);
        Ok(())
    }

    /// A per-cycle output buffer sized for the loaded program and seeded with
    /// the current (after [`load`](Self::load): the start) pose, so the first
    /// [`cycle_into`](Self::cycle_into) has nothing left to allocate.
    pub fn output_buffer(&self) -> IplOutput {
        let mut out = IplOutput::with_capacity(self.aux_capacity, self.switch_capacity);
        self.seed_output(&mut out);
        out
    }

    fn advance(&mut self) -> Result<(), CncError> {
        self.time += self.cycle_time;
        let ovr = self.effective_override();

        match self.state {
            IplState::Idle | IplState::Finished => {}
            IplState::Paused => {
                if ovr > 0.0 {
                    // Resume: replan from standstill. The cursor may still sit
                    // on a move boundary that was never planned (paused there).
                    if self.current_move().is_some() {
                        self.plan_move_traj(ovr)?;
                        self.state = IplState::Running;
                    } else {
                        self.enter_next(ovr)?;
                    }
                }
            }
            IplState::StepHold => {
                if self.step_pending && ovr > 0.0 {
                    self.step_pending = false;
                    self.plan_move_traj(ovr)?;
                    self.state = IplState::Running;
                }
            }
            IplState::Dwelling => {
                if ovr > 0.0 {
                    self.dwell_remaining -= self.cycle_time;
                    if self.dwell_remaining <= 0.0 {
                        self.enter_next(ovr)?;
                    }
                }
            }
            IplState::Running | IplState::Pausing => {}
        }

        if self.state == IplState::Running {
            if ovr <= 0.0 {
                if self.v_s <= EPS_V {
                    self.v_s = 0.0;
                    self.a_s = 0.0;
                    self.state = IplState::Paused;
                } else {
                    self.plan_stop_traj()?;
                    self.state = IplState::Pausing;
                }
            } else if (ovr - self.traj_override).abs() > 1e-9
                || (self.single_step && self.planned_v_exit != 0.0)
            {
                // Override changed mid-segment (or single-step was switched on,
                // which requires stopping at the segment end): retarget from
                // the current state
                self.plan_move_traj(ovr)?;
            }
        }

        match self.state {
            IplState::Running => self.step_running(ovr)?,
            IplState::Pausing => self.step_pausing()?,
            _ => {}
        }

        Ok(())
    }

    // --- internals -------------------------------------------------------

    fn first_move(&self) -> Option<&GeoMove> {
        self.queue.iter().find_map(|e| match e {
            GeoElem::Move(m) => Some(m),
            _ => None,
        })
    }

    fn current_move(&self) -> Option<&GeoMove> {
        match self.queue.get(self.cursor) {
            Some(GeoElem::Move(m)) => Some(m),
            _ => None,
        }
    }

    fn current_plan(&self) -> &PlannedSegment {
        &self.plan[self.plan_pos]
    }

    /// Enter the next queue element(s): fire events, start dwells, or plan
    /// the next move. `self.cursor` must point at the element to enter.
    fn enter_next(&mut self, ovr: f64) -> Result<(), CncError> {
        loop {
            match self.queue.get(self.cursor) {
                None => {
                    self.state = IplState::Finished;
                    self.v_s = 0.0;
                    self.a_s = 0.0;
                    return Ok(());
                }
                Some(GeoElem::Event(e)) => {
                    self.pending_events.push(e.clone());
                    self.last_src_line = e.src_line;
                    self.cursor += 1;
                }
                Some(GeoElem::Dwell { seconds, src_line }) => {
                    self.v_s = 0.0;
                    self.a_s = 0.0;
                    self.dwell_remaining = *seconds;
                    self.last_src_line = *src_line;
                    self.cursor += 1;
                    self.state = IplState::Dwelling;
                    return Ok(());
                }
                Some(GeoElem::Move(_)) => {
                    while self.plan[self.plan_pos].queue_index < self.cursor {
                        self.plan_pos += 1;
                    }
                    debug_assert_eq!(self.plan[self.plan_pos].queue_index, self.cursor);
                    self.s_local = 0.0;
                    self.a_s = 0.0;
                    self.switch_pos = 0;
                    if self.single_step {
                        self.v_s = 0.0;
                        self.state = IplState::StepHold;
                    } else if ovr <= 0.0 {
                        self.v_s = 0.0;
                        self.state = IplState::Paused;
                    } else {
                        self.plan_move_traj(ovr)?;
                        self.state = IplState::Running;
                    }
                    return Ok(());
                }
            }
        }
    }

    /// Plan the jerk-limited s-profile for the current move from the current
    /// state, honoring the override.
    fn plan_move_traj(&mut self, ovr: f64) -> Result<(), CncError> {
        let seg = self.current_plan().clone();
        let (src_line, obj_no) = {
            let mv = self
                .current_move()
                .expect("plan_move_traj called off a move element");
            (mv.src_line, mv.obj_no)
        };
        self.last_src_line = src_line;
        self.last_obj_no = obj_no;

        let v_max = seg.v_cap * ovr;
        // Exit velocity: the planned junction velocity, clamped to the current
        // cruise cap (rsruckig requires target ≤ max) and to what is actually
        // reachable in the remaining distance (prevents the time-optimal
        // profile from backing up to get a run-up).
        let remaining = (seg.length - self.s_local).max(0.0);
        let a_eff = seg.accel * self.lookahead.accel_margin;
        let reachable = (self.v_s * self.v_s + 2.0 * a_eff * remaining).sqrt();
        let mut v_exit = seg.v_exit.min(v_max).min(reachable);
        if self.single_step {
            v_exit = 0.0;
        }

        self.input.control_interface = ControlInterface::Position;
        self.input.current_position[0] = self.s_local;
        self.input.current_velocity[0] = self.v_s;
        self.input.current_acceleration[0] = self.a_s;
        self.input.target_position[0] = seg.length;
        self.input.target_velocity[0] = v_exit;
        self.input.target_acceleration[0] = 0.0;
        self.input.max_velocity[0] = v_max.max(v_exit);
        self.set_accel_limits(seg.accel, seg.decel);
        self.input.max_jerk[0] = self.limits.max_jerk;

        self.calculate(src_line)?;
        self.traj_override = ovr;
        self.planned_v_exit = v_exit;
        Ok(())
    }

    /// Plan an immediate jerk-limited stop from the current state
    /// (velocity control interface; position is unconstrained).
    fn plan_stop_traj(&mut self) -> Result<(), CncError> {
        let src_line = self.last_src_line;
        let decel = self.current_decel();
        self.input.control_interface = ControlInterface::Velocity;
        self.input.current_position[0] = self.s_local;
        self.input.current_velocity[0] = self.v_s;
        self.input.current_acceleration[0] = self.a_s;
        self.input.target_velocity[0] = 0.0;
        self.input.target_acceleration[0] = 0.0;
        // Braking to a stop: the deceleration limit is the binding one, and
        // the velocity interface reads it from `max_acceleration`.
        self.set_accel_limits(decel, decel);
        self.input.max_jerk[0] = self.limits.max_jerk;
        self.stop_s_offset = 0.0;
        self.calculate(src_line)
    }

    /// The deceleration limit in force where the path currently is.
    fn current_decel(&self) -> f64 {
        self.plan
            .get(self.plan_pos)
            .map_or(self.limits.max_acceleration, |p| p.decel)
    }

    /// Hand rsruckig this segment's acceleration and deceleration limits.
    /// Symmetric limits stay on the plain `max_acceleration` path; an `E`
    /// word that separates them sets `min_acceleration` as well.
    fn set_accel_limits(&mut self, accel: f64, decel: f64) {
        self.input.max_acceleration[0] = accel;
        if (accel - decel).abs() <= f64::EPSILON * accel.max(decel) {
            self.input.min_acceleration = None;
        } else {
            match &mut self.input.min_acceleration {
                Some(v) => v[0] = -decel,
                slot => *slot = Some(daov_stack![-decel]),
            }
        }
    }

    fn calculate(&mut self, src_line: usize) -> Result<(), CncError> {
        match self.otg.calculate(&self.input, &mut self.traj) {
            Ok(RuckigResult::Working) | Ok(RuckigResult::Finished) => {
                self.traj_time = 0.0;
                Ok(())
            }
            Ok(other) => Err(CncError::Otg {
                line: src_line,
                message: format!("trajectory calculation failed: {other:?}"),
            }),
            Err(e) => Err(CncError::Otg {
                line: src_line,
                message: e.to_string(),
            }),
        }
    }

    fn sample_traj(&mut self) -> (f64, f64, f64) {
        let mut pos = daov_stack![0.0];
        let mut vel = daov_stack![0.0];
        let mut acc = daov_stack![0.0];
        self.traj.at_time(
            self.traj_time,
            &mut Some(&mut pos),
            &mut Some(&mut vel),
            &mut Some(&mut acc),
            &mut None,
            &mut None,
        );
        (pos[0], vel[0], acc[0])
    }

    fn step_running(&mut self, ovr: f64) -> Result<(), CncError> {
        let mut t = self.traj_time + self.cycle_time;
        loop {
            let duration = self.traj.get_duration();
            if t < duration {
                break;
            }
            // Segment complete: snap to its exact end state
            t -= duration;
            let seg = self.current_plan().clone();
            self.s_local = seg.length;
            self.v_s = self.planned_v_exit;
            self.a_s = 0.0;
            self.update_pose();
            self.fire_switches(f64::INFINITY);
            self.s_done += seg.length;
            self.s_local = 0.0;
            self.cursor += 1;
            self.enter_next(ovr)?;
            if self.state != IplState::Running {
                // Dwell / hold / pause / finished: the leftover cycle time is
                // absorbed by that state (bounded by one cycle).
                return Ok(());
            }
        }
        self.traj_time = t;
        let (s, v, a) = self.sample_traj();
        let seg_len = self.current_plan().length;
        // Monotonicity guard: never move backward along the path
        self.s_local = s.clamp(self.s_local, seg_len);
        self.v_s = v.max(0.0);
        self.a_s = a;
        self.update_pose();
        self.fire_switches(self.s_local);
        Ok(())
    }

    fn step_pausing(&mut self) -> Result<(), CncError> {
        let duration = self.traj.get_duration();
        self.traj_time = (self.traj_time + self.cycle_time).min(duration);
        let (s_raw, v, a) = self.sample_traj();
        // The stop trajectory runs in the coordinates of the segment it was
        // planned in; stop_s_offset rebases samples after boundary crossings.
        let mut s = (s_raw - self.stop_s_offset).max(self.s_local);
        self.v_s = v.max(0.0);
        self.a_s = a;

        // The stop profile may run past the current segment's end when the
        // junction there was a blend: walk forward into following moves.
        loop {
            let seg_len = self.current_plan().length;
            if s <= seg_len {
                break;
            }
            let next_is_adjacent_move =
                matches!(self.queue.get(self.cursor + 1), Some(GeoElem::Move(_)));
            if !next_is_adjacent_move {
                // Should not happen (v_exit = 0 before non-move elements
                // guarantees the stop fits), but never leave the segment.
                s = seg_len;
                break;
            }
            self.fire_switches(f64::INFINITY);
            s -= seg_len;
            self.stop_s_offset += seg_len;
            self.s_done += seg_len;
            self.cursor += 1;
            self.plan_pos += 1;
            self.switch_pos = 0;
        }
        self.s_local = s;
        self.update_pose();
        self.fire_switches(self.s_local);

        if self.traj_time >= duration || self.v_s <= EPS_V {
            self.v_s = 0.0;
            self.a_s = 0.0;
            self.state = IplState::Paused;
        }
        Ok(())
    }

    /// Report every switch point of the current move up to path position `s`
    /// that has not been reported yet. `f64::INFINITY` drains the move's list,
    /// which is what leaving the element does.
    fn fire_switches(&mut self, s: f64) {
        let mut fired = core::mem::take(&mut self.pending_switches);
        if let Some(GeoElem::Move(mv)) = self.queue.get(self.cursor) {
            while let Some(sp) = mv.switch_points.get(self.switch_pos) {
                if sp.position > s {
                    break;
                }
                fired.push(*sp);
                self.switch_pos += 1;
            }
        }
        self.pending_switches = fired;
    }

    /// Update path point, tangent and aux values from `s_local`.
    ///
    /// The aux buffers are taken out of `self`, refilled in place and put
    /// back, so no allocation happens as long as their capacity (reserved in
    /// [`load`](Self::load)) covers the move's aux width.
    fn update_pose(&mut self) {
        let v_s = self.v_s;
        let s_local = self.s_local;
        let mut aux = core::mem::take(&mut self.aux_now);
        let mut aux_vel = core::mem::take(&mut self.aux_vel_now);

        let pose = self.current_or_last_move().map(|mv| {
            let param_len = mv.param_length();
            let s = s_local.clamp(0.0, param_len);
            let geo_len = mv.geo.length();
            let s_geo = s.min(geo_len);
            let point = mv.geo.point_at(s_geo);
            let tangent = if geo_len > 0.0 {
                mv.geo.tangent_at(s_geo)
            } else {
                [0.0; 3]
            };
            let u = if param_len > 0.0 { s / param_len } else { 1.0 };
            aux.clear();
            aux_vel.clear();
            for (a0, a1) in mv.aux_start.iter().zip(mv.aux_end.iter()) {
                let delta = a1 - a0;
                aux.push(a0 + delta * u);
                aux_vel.push(if param_len > 0.0 {
                    delta / param_len * v_s
                } else {
                    0.0
                });
            }
            (point, tangent)
        });

        self.aux_now = aux;
        self.aux_vel_now = aux_vel;
        if let Some((point, tangent)) = pose {
            self.point = point;
            self.tangent = tangent;
        }
    }

    fn current_or_last_move(&self) -> Option<&GeoMove> {
        if let Some(GeoElem::Move(m)) = self.queue.get(self.cursor) {
            return Some(m);
        }
        // After the last move (finished / dwell): the previous move
        self.queue[..self.cursor.min(self.queue.len())]
            .iter()
            .rev()
            .find_map(|e| match e {
                GeoElem::Move(m) => Some(m),
                _ => None,
            })
    }

    /// Copy the current state (everything but the pending events) into `out`,
    /// reusing the buffer's capacity.
    fn seed_output(&self, out: &mut IplOutput) {
        out.state = self.state;
        out.path_position = self.point;
        out.path_tangent = self.tangent;
        out.path_velocity = self.v_s;
        out.path_acceleration = self.a_s;
        out.aux.clear();
        out.aux.extend_from_slice(&self.aux_now);
        out.aux_velocity.clear();
        out.aux_velocity.extend_from_slice(&self.aux_vel_now);
        out.src_line = self.last_src_line;
        out.obj_no = self.last_obj_no;
        out.s_total = self.s_done + self.s_local;
        out.progress = if self.total_length > 0.0 {
            (out.s_total / self.total_length).min(1.0)
        } else {
            1.0
        };
    }

    fn fill_output(&mut self, out: &mut IplOutput) {
        self.seed_output(out);
        // Hand over the events crossed this cycle without dropping either
        // vector's capacity.
        out.events.clear();
        out.events.append(&mut self.pending_events);
        out.switch_points.clear();
        out.switch_points.append(&mut self.pending_switches);
    }
}
